sp_widget.client_script:
api.controller = function($scope) { 
    $scope.goToSubmitFeedback = function() { 
        var recordProducerSysId = '-1'; 
        var url = '/sp?id=sc_cat_item&sys_id=' + recordProducerSysId; 
        window.location.href = url; 
    }; 
};

sp_widget.css:
.custom-action-card-feedback {
    background: #fcf7f8; /* very light rose background */
    border-radius: 12px;
    padding: 24px 20px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.04);
    border: 1px solid #eedee2; /* soft rose-gray border */
    text-align: center;
}

.custom-action-card-feedback h4 {
    margin-bottom: 16px;
    font-weight: 600;
    color: #6e4b50; /* warm muted heading text */
    font-size: 18px;
}

.action-btn-feedback {
    background: #f2d4d9; /* soft rose-pink button */
    color: #5a3e42; /* deeper warm gray text */
    padding: 10px 18px;
    font-size: 14px;
    border: none;
    border-radius: 6px;
    width: 100%;
    cursor: pointer;
    transition: background 0.2s ease;
}

.action-btn-feedback:hover {
    background: #e6c5cb; /* slightly darker on hover */
}
